  "system-design-52-ssrf": {
    kind: "seq",
    title: "SSRF: making your own server fetch a secret",
    actors: [{ name: "Attacker" }, { name: "Your API", sub: "inside the cloud" }, { name: "Metadata service", sub: "169.254.169.254" }],
    steps: [
      { from: 0, to: 1, label: "POST /preview-link {url: news site}", title: "A harmless feature: fetch a link preview", note: "Your API has a feature that takes a URL and fetches the page to show a preview. For a normal news site this works as intended." },
      { from: 1, to: 1, self: true, label: "fetch the URL as asked", title: "The server trusts whatever URL it is given", note: "The request is made from inside your network, so it comes from a machine that can reach things the outside world cannot. That power is what SSRF (server-side request forgery) abuses." },
      { from: 0, to: 1, label: "POST /preview-link {url: 169.254...}", title: "The attacker sends an internal address instead", note: "The address 169.254.169.254 is the cloud metadata endpoint. Every cloud server can ask it about itself, but nobody outside can reach it, so the attacker sends your server to do it." },
      { from: 1, to: 2, label: "GET .../credentials", title: "Your server calls the metadata service for them", note: "The metadata service sees a request from a real server inside the cloud and has no reason to refuse it." },
      { from: 2, to: 1, label: "temporary cloud credentials", title: "Secret keys come back to the server", note: "The reply holds temporary credentials, the keys the server uses to log in to cloud services. They were meant for your code only." },
      { from: 1, to: 0, label: "link preview containing the keys", title: "The server hands the keys to the attacker", note: "The feature simply shows what it fetched. Now the attacker can act with the server's cloud permissions. This is the pattern behind the Capital One breach in 2019." },
      { from: 1, to: 1, self: true, label: "block private IPs, allow-list hosts", title: "The fix: limit where the server may go", note: "Allow-list the destinations, block private and metadata addresses after DNS lookup and after redirects, require IMDSv2, and give the server a role with few permissions, so stolen keys can do very little." },
    ],
  },
