  "system-design-55-docker-layer-cache": {
    kind: "array",
    title: "Why Dockerfile order decides build speed",
    cells: ["FROM", "COPY pkg", "npm ci", "COPY src", "build"],
    indexLabels: ["layer 1", "layer 2", "layer 3", "layer 4", "layer 5"],
    steps: [
      { title: "First build: every layer is built", mark: [0, 1, 2, 3, 4], note: "Docker runs each Dockerfile step in order and saves the result of each one as a layer. The first build has nothing saved, so installing the dependencies is slow." },
      { title: "You change one source file", pointers: [{ at: 3, label: "changed" }], note: "Only code under src changed. package.json is exactly the same as before, so the dependency files have not changed." },
      { title: "Layers 1 to 3 come from the cache", done: [0, 1, 2], pointers: [{ at: 3, label: "changed" }], note: "Docker sees that the inputs to the first three steps are unchanged and reuses the saved layers. The slow npm ci step is skipped, because package files were copied before the source code." },
      { title: "Only layers 4 and 5 are rebuilt", done: [0, 1, 2], mark: [3, 4], note: "A changed layer forces every layer after it to be rebuilt. Here that means only copying the source and compiling it, so the build takes seconds, not minutes." },
      { title: "The naive order: copy everything first", cells: ["FROM", "COPY all", "install", "build", "run"], pointers: [{ at: 1, label: "changed" }], note: "With COPY . . before the install, the second layer contains your code. Any edit to any file changes that layer, so Docker cannot trust the layers after it." },
      { title: "Now every code edit reinstalls dependencies", cells: ["FROM", "COPY all", "install", "build", "run"], done: [0], mark: [1, 2, 3, 4], note: "Only the first layer is cached. The slow install runs again on every build. Copying the dependency files first is how the better Dockerfile avoids this." },
    ],
  },
